  &lt;div&gt;
    &lt;h1&gt;Llistat de cursos&lt;/h1&gt;
    &lt;ul&gt;
      &lt;li v-for="course in courses" :key="course.id"&gt;
        {{ course.name }} - {{ course.duration }}
        &lt;button @click="deleteCourse(course.id)"&gt;Esborrar&lt;/button&gt;
      &lt;/li&gt;
    &lt;/ul&gt;
  &lt;/div&gt;
&lt;/template&gt;

&lt;script&gt;
import { getAllCourses, deleteCourse } from '../api/coursesService';

export default {
  name: 'CourseList',
  data() {
    return {
      courses: [],
    };
  },
  async created() {
    // Carrega els cursos quan es monte el component
    this.courses = await getAllCourses();
  },
  methods: {
    async deleteCourse(id) {
      try {
        await deleteCourse(id);
        this.courses = this.courses.filter(course =&gt; course.id !== id);
      } catch (error) {
        console.error('Error esborrant el curs:', error);
      }
    },
  },
};
&lt;/script&gt;
